package zombie.iso;
public final class IsoGridSquare {public int x,y,z,invalidations;public boolean reachable=true;public final zombie.util.list.PZArrayList<IsoObject> objects=new zombie.util.list.PZArrayList<>();public IsoGridSquare(int x,int y,int z){this.x=x;this.y=y;this.z=z;}public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public zombie.util.list.PZArrayList<IsoObject> getObjects(){return objects;}public boolean isAdjacentTo(IsoGridSquare o){return o!=null&&z==o.z&&Math.abs(x-o.x)<=1&&Math.abs(y-o.y)<=1;}public boolean canReachTo(IsoGridSquare o){return reachable&&isAdjacentTo(o);}public void invalidateRenderChunkLevel(long flags){invalidations++;}}
